package com.vandorlabs.neoforge.gear;

import com.vandorlabs.redstone.ChannelList;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.*;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Real private block items, all mounting faces, held consumption, world ticks and process restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearRuntimeChecks {
    private static final List<BlockPos> ROOTS=new ArrayList<>();
    private static int stage,ticks,checks;private static boolean running;private static long stablePublications;private static int stableRevisions;
    private static String phase(){return System.getProperty("vandorlabs.gearPhase","");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native arm stage="+stage+" ticks="+ticks+": "+why);}
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel world){super(world,new com.mojang.authlib.GameProfile(new UUID(0,40210),"GearRuntime"));}}
    private static NativeGearEntity owner(ServerLevel world,BlockPos pos){var tile=NativeGearFormation.at(world,pos);need(tile!=null,"installed gear "+pos);return tile;}
    private static List<BlockPos> positions(){var positions=new ArrayList<BlockPos>();int index=0;for(Direction mount:Direction.values())for(var kind:new NativeGearDefinition[]{NativeGearDefinition.EXTENDER,NativeGearDefinition.ROTATING,NativeGearDefinition.LARGE_EXTENDER,NativeGearDefinition.LARGE_ROTATING})for(int height:new int[]{1,2})positions.add(new BlockPos(16000+index++%8*12,120,16000+(index-1)/8*12));return positions;}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(phase().isEmpty())return;try{ROOTS.clear();ROOTS.addAll(positions());var world=event.getServer().overworld();for(BlockPos root:ROOTS)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){world.setChunkForced(root.getX()/16+x,root.getZ()/16+z,true);world.getChunk(root.getX()/16+x,root.getZ()/16+z);}if(phase().equals("read")){for(BlockPos pos:ROOTS){var tile=owner(world,pos);var saved=tile.saveWithoutMetadata(world.registryAccess());need(!tile.inert()&&tile.controller(),"healthy saved controller "+pos);need(saved.getString("NativeGearTestMarker").equals("retained")&&saved.getByteArray("NativeGearOpaque").length==1024,"opaque original fields retained");need(Double.doubleToRawLongBits(tile.progress())==Double.doubleToRawLongBits(saved.getDouble("NativeGearExpectedPhase")),"exact partially moving saved phase "+pos);need(tile.progress()>0&&tile.progress()<1,"restart was not endpoint-only");}running=true;stage=10;ticks=0;return;}
        var actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);int index=0;for(Direction mount:Direction.values())for(var kind:new NativeGearDefinition[]{NativeGearDefinition.EXTENDER,NativeGearDefinition.ROTATING,NativeGearDefinition.LARGE_EXTENDER,NativeGearDefinition.LARGE_ROTATING})for(int height:new int[]{1,2}){var root=ROOTS.get(index++);for(int x=-4;x<=4;x++)for(int y=-4;y<=4;y++)for(int z=-4;z<=4;z++)world.setBlock(root.offset(x,y,z),Blocks.AIR.defaultBlockState(),18);world.setBlock(root.relative(mount.getOpposite()),Blocks.STONE.defaultBlockState(),3);actor.setPos(root.getX()+.5,root.getY()+1,root.getZ()-3);actor.setYRot(0);var stack=new ItemStack(NativeGearBindings.ITEMS.get(kind.id),8);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(int member=0;member<height;member++){BlockPos cell=root.relative(mount,member),support=cell.relative(mount.getOpposite());var hit=new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(mount.getNormal()).scale(.5)),mount,support,false);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,hit).consumesAction(),"actual Survival placement "+kind+"/"+mount+"/"+member);need(owner(world,cell).mount()==mount,"placed mount "+kind+"/"+mount);need(stack.getCount()==7-member,"exact one consumed owner "+kind+"/"+mount);}}
        running=true;stage=0;ticks=0;
    }catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][gear-runtime] "+phase()+" FAIL "+failure);event.getServer().halt(false);}}
    private static NativeGearSettings trigger(NativeGearSettings s){return new NativeGearSettings(1,s.direction(),ChannelList.EMPTY,false,s.pushBlocks(),s.rotatePayload(),s.middleHinge(),s.join(),s.joinRange(),s.carryLoad(),s.loadHeight(),s.startAngle(),s.activeAngle(),s.activeExtension(),s.footFacing());}
    private static void power(ServerLevel world,boolean on){for(BlockPos pos:ROOTS){var tile=owner(world,pos);world.setBlock(pos.offset(NativeGearOrientation.vector(tile.mount(),new BlockPos(1,0,0))),on?Blocks.REDSTONE_BLOCK.defaultBlockState():Blocks.AIR.defaultBlockState(),3);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{var world=event.getServer().overworld();if(++ticks>240)throw new AssertionError("Arm runtime timeout stage="+stage+" unfinished="+ROOTS.stream().map(pos->owner(world,pos)).filter(tile->tile.progress()!=(stage==11?1:0)||tile.blocked()).map(tile->tile.getBlockPos()+"/"+tile.definition()+"/"+tile.mount()+"/h"+(tile.assembly()==null?0:tile.assembly().columnHeight())+"/p"+tile.progress()+"/target="+tile.target()+"/error="+tile.error()).limit(16).toList());
        if(stage==0){for(int i=0;i<ROOTS.size();i++){var tile=owner(world,ROOTS.get(i));if(!tile.controller()||tile.assembly().columnHeight()!=i%2+1)return;need(tile.members().size()==i%2+1,"one complete column");need(!tile.collisionBoxes().isEmpty(),"actual emitted collision");need(tile.configure(trigger(tile.settings()),true),"configured trigger");}stablePublications=NativeGearTargets.indexPublications();stableRevisions=ROOTS.stream().mapToInt(pos->owner(world,pos).visual().revision()).sum();power(world,true);stage=1;ticks=0;return;}
        if(stage==1){for(BlockPos pos:ROOTS){var tile=owner(world,pos);need(!tile.blocked(),"real placement stroke blocked "+pos+" "+tile.error());if(tile.progress()>.65)return;}power(world,false);stage=2;ticks=0;return;}
        if(stage==2){for(BlockPos pos:ROOTS){var tile=owner(world,pos);need(!tile.blocked(),"reversal blocked "+tile.error());if(tile.progress()!=1)return;}power(world,true);stage=3;ticks=0;return;}
        if(stage==3){for(BlockPos pos:ROOTS){var tile=owner(world,pos);need(!tile.blocked(),"second stroke blocked "+tile.error());if(tile.progress()>.6)return;need(tile.progress()>.2,"simultaneous moving checkpoint");}need(NativeGearTargets.indexPublications()==stablePublications,"motion and setting updates reuse source index entries");int updates=ROOTS.stream().mapToInt(pos->owner(world,pos).visual().revision()).sum()-stableRevisions;need(updates>48,"actual repeated motion publications");System.out.println("[vandorlabs][gear-runtime] index beforeReinsertions="+updates+" afterReinsertions="+(NativeGearTargets.indexPublications()-stablePublications)+" loadedSources="+stablePublications);for(BlockPos pos:ROOTS){var tile=owner(world,pos);var saved=tile.saveWithoutMetadata(world.registryAccess());saved.putString("NativeGearTestMarker","retained");saved.putByteArray("NativeGearOpaque",new byte[1024]);saved.putDouble("NativeGearExpectedPhase",tile.progress());tile.loadWithComponents(saved,world.registryAccess());tile.setChanged();}running=false;System.out.println("[vandorlabs][gear-runtime] write PASS assemblies="+ROOTS.size()+" checks="+checks+" actualSurvival/sixFaces/regularLarge/extenderRotating/formation/redstone/reversal/movingSave");event.getServer().halt(false);return;}
        if(stage==10){for(BlockPos pos:ROOTS){var tile=owner(world,pos);if(!tile.controller()||tile.progress()!=0)return;need(!tile.blocked(),"resumed stroke blocked "+tile.error());}power(world,false);stage=11;ticks=0;return;}
        if(stage==11){for(BlockPos pos:ROOTS){var tile=owner(world,pos);if(tile.progress()!=1)return;need(!tile.blocked(),"post-restart reversal blocked");}running=false;System.out.println("[vandorlabs][gear-runtime] read PASS assemblies="+ROOTS.size()+" checks="+checks+" exactMovingNBT/opaqueRetention/deferredReformation/resume/reversal");event.getServer().halt(false);}
    }catch(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-runtime] "+phase()+" FAIL "+failure);event.getServer().halt(false);}}
}
